#include <iostream>
#include <cmath>
using namespace std;

int floorf(double x) {
    return x >= 0 ? static_cast<int>(x) : static_cast<int>(x) - 1;
}

int calculate_f(int x) {
    int floor_x = floorf(x);
    int floor_sqrt_x = floorf(sqrt(x));
    int floor_cbrt_x = floorf(cbrt(x));
    return floor_x + floor_sqrt_x + floor_cbrt_x;
}

int main() {
    int count = 0;
    for (int i = 1; i <= 2023; ++i) {
        int result = calculate_f(i);
        if (result <= 2023) count++;
    }
    cout << count << endl;
    return 0;
}

